"""Animate the five approved storyboard stills (AI-generated by the owner, upscaled with Real-ESRGAN) into the 30 s reel.
Per scene: slow camera move, a flowing swirl in the accretion disk (flow-map advection that stays within a few degrees, so the
disk's shape holds), debris and ember particles streaming toward the black hole, drifting stars, grain; crossfades as planned.
python3 animate.py <worker> <n_workers>   (frames to renders/frames) | python3 animate.py still <t> <out.png>"""
import sys, math, numpy as np
from pathlib import Path
from PIL import Image
from scipy.ndimage import map_coordinates, gaussian_filter
H = Path(__file__).resolve().parent; P = H.parent / "assets" / "bh_panels"
W, Hh, FPS, T = 1080, 1920, 30, 30.0
sst = lambda a, b, x: (lambda u: u * u * (3 - 2 * u))(min(1.0, max(0.0, (x - a) / (b - a))))
lerp = lambda a, b, u: a + (b - a) * u
IMG = {i: np.asarray(Image.open(P / f"scene{i}.png").convert("RGB"), np.float32)[:, 8:-8] / 255.0 for i in range(1, 6)}   # trim collage dividers
# black hole centre, shadow radius, outer swirl radius (pixels in each upscaled panel)
BH = {1: (712, 280, 170, 400), 2: (520, 540, 250, 520), 3: (592, 110, 90, 260), 4: (568, 150, 80, 280), 5: (450, 394, 90, 280)}
# debris stream start point (on/near Earth) per scene; None = no stream
SRC = {1: None, 2: None, 3: (512, 520), 4: (462, 900), 5: (292, 1560)}
# camera: (zoom start, zoom end, centre-y fraction start, end, centre-x fraction)
CAM = {1: (1.0, 1.07, 0.5, 0.5, 0.5), 2: (1.0, 1.09, 0.52, 0.46, 0.5), 3: (1.0, 1.04, 0.58, 0.46, 0.5),
       4: (1.0, 1.05, 0.62, 0.36, 0.5), 5: (1.12, 1.0, 0.42, 0.48, 0.5)}
SCENES = [(1, 0, 5), (2, 5, 10), (3, 10, 16), (4, 16, 24), (5, 24, 30)]
XF = {(1, 2): 0.5, (2, 3): 0.4, (3, 4): 0.0, (4, 5): 0.6}

def swirl(i, t):
    """Disk flow: two copies advected along the orbit (inner faster), cross-faded on a sawtooth so the offset never grows."""
    a = IMG[i]; h, w, _ = a.shape; cx, cy, r0, R = BH[i]
    ys, xs = np.mgrid[0:h, 0:w].astype(np.float32); dx, dy = xs - cx, ys - cy; r = np.hypot(dx, dy) + 1e-3
    mask = np.clip((r - r0 * 0.98) / 12, 0, 1) * np.clip((R - r) / (R * 0.35), 0, 1)
    om = 0.22 * (r0 / r) ** 1.5                                  # rad per cycle
    Pd = 2.4; out = np.zeros_like(a)
    for ph in (0.0, 0.5):
        f = ((t / Pd) + ph) % 1.0; wgt = 1 - abs(2 * f - 1)
        ang = -om * (f - 0.5) * mask
        c, s = np.cos(ang), np.sin(ang); sx, sy = cx + dx * c - dy * s, cy + dx * s + dy * c
        warped = np.stack([map_coordinates(a[..., k], [sy, sx], order=1, mode="nearest") for k in range(3)], -1)
        out += warped * wgt
    return out

# Earth in each panel: centre x, y, radius (pixels); spin rate (rad/s); drift toward the hole (pixels over the scene)
EARTH = {1: (412, 1166, 432, 0.05, 40), 2: (660, 1416, 352, 0.055, 55), 3: (322, 840, 270, 0.03, 0), 4: (163, 1150, 275, 0.03, 0)}

def spin(i, img, t):
    """Rotate Earth's surface about its axis inside its disk (outline fixed); two phases cross-faded so the offset stays small."""
    if i not in EARTH: return img
    cx, cy, R, om, _ = EARTH[i]; h, w, _ = img.shape
    x0, x1, y0, y1 = max(0, cx - R), min(w, cx + R), max(0, cy - R), min(h, cy + R)
    ys, xs = np.mgrid[y0:y1, x0:x1].astype(np.float32); X, Y = (xs - cx) / R, (ys - cy) / R
    inside = X * X + Y * Y < 1; Z = np.sqrt(np.clip(1 - X * X - Y * Y, 0, 1)); lam = np.arctan2(X, Z); rr = np.sqrt(np.clip(1 - Y * Y, 1e-6, 1))
    feather = np.clip((1 - np.sqrt(X * X + Y * Y)) / 0.06, 0, 1) * inside
    Pd = 6.0; acc = np.zeros((y1 - y0, x1 - x0, 3), np.float32)
    for ph in (0.0, 0.5):
        f = ((t / Pd) + ph) % 1.0; wgt = 1 - abs(2 * f - 1); d = om * Pd * (f - 0.5)
        lam2 = np.clip(lam - d, -1.45, 1.45); sx = cx + rr * np.sin(lam2) * R; sy = ys
        acc += np.stack([map_coordinates(img[..., k], [sy, sx], order=1, mode="nearest") for k in range(3)], -1) * wgt
    out = img.copy(); reg = out[y0:y1, x0:x1]; out[y0:y1, x0:x1] = reg * (1 - feather[..., None]) + acc * feather[..., None]
    return out

def drift(i, img, tl, dur):
    """Move Earth slowly toward the black hole by shifting its disk region (background kept)."""
    if i not in EARTH or EARTH[i][4] == 0: return img
    cx, cy, R, _, dist = EARTH[i]; bx, by = BH[i][:2]; v = np.array([bx - cx, by - cy], np.float32); v /= np.linalg.norm(v)
    sh = v * dist * (tl / dur); h, w, _ = img.shape
    ys, xs = np.mgrid[0:h, 0:w].astype(np.float32); r = np.hypot(xs - cx - sh[0], ys - cy - sh[1])
    m = np.clip((R * 1.04 - r) / (R * 0.06), 0, 1)
    moved = np.stack([map_coordinates(img[..., k], [ys - sh[1], xs - sh[0]], order=1, mode="nearest") for k in range(3)], -1)
    return img * (1 - m[..., None]) + moved * m[..., None]

def debris_flow(i, img, t):
    """Scenes 3-5: the painted debris, dust and vapour stream toward the hole (flow map; Earth and the shadow are excluded)."""
    if i < 3: return img
    h, w, _ = img.shape; bx, by, r0, _ = BH[i]
    ys, xs = np.mgrid[0:h, 0:w].astype(np.float32); vx, vy = bx - xs, by - ys; d = np.hypot(vx, vy) + 1e-3; vx, vy = vx / d, vy / d
    m = np.clip((d - r0 * 1.15) / 40, 0, 1)
    if i in EARTH: cx, cy, R = EARTH[i][:3]; m *= np.clip((np.hypot(xs - cx, ys - cy) - R * 0.98) / 30, 0, 1)
    speed = 34 * (1 + 600 / (d + 300))                              # pixels per cycle, faster near the hole
    Pd = 1.8; acc = np.zeros_like(img)
    for ph in (0.0, 0.5):
        f = ((t / Pd) + ph) % 1.0; wgt = 1 - abs(2 * f - 1); k = speed * (f - 0.5) * m
        acc += np.stack([map_coordinates(img[..., c], [ys - vy * k, xs - vx * k], order=1, mode="nearest") for c in range(3)], -1) * wgt
    return acc

def flicker(i, img, t):
    """Hot cracks and embers pulse; stars twinkle."""
    r, g, b = img[..., 0], img[..., 1], img[..., 2]
    hot = np.clip((r - 0.55) * 3, 0, 1) * np.clip((r - g * 1.35) * 4, 0, 1) * (b < 0.35)
    h, w = r.shape; ys, xs = np.mgrid[0:h, 0:w]
    puls = 1 + 0.28 * np.sin(t * 7.0 + xs * 0.031 + ys * 0.017) * np.sin(t * 3.1 + ys * 0.023)
    img = img * (1 + hot[..., None] * (puls[..., None] - 1))
    lum = (r + g + b) / 3; star = np.clip((lum - gaussian_filter(lum, 4) - 0.18) * 6, 0, 1)            # isolated bright points only
    seed = np.sin(gaussian_filter(xs.astype(np.float32), 0) * 0.37 + ys * 0.91) * 43758.5 % 6.283
    tw = 1 + 0.4 * star * np.sin(t * 4.7 + seed)
    return img * tw[..., None]

def view(i, u):
    """Crop rectangle (x0, y0, cw, ch) of panel i for scene progress u, filling 9:16."""
    a = IMG[i]; h, w, _ = a.shape; z0, z1, y0, y1, xc = CAM[i]; z = lerp(z0, z1, u)
    cw = min(w, h * W / Hh) / z; ch = cw * Hh / W
    cx = min(max(xc * w, cw / 2), w - cw / 2); cy = min(max(lerp(y0, y1, u) * h, ch / 2), h - ch / 2)
    return cx - cw / 2, cy - ch / 2, cw, ch

def render_scene(i, tl, dur):
    u = tl / dur; src = flicker(i, drift(i, spin(i, debris_flow(i, swirl(i, tl), tl), tl), tl, dur), tl); x0, y0, cw, ch = view(i, sst(0, 1, u) * 0.7 + u * 0.3)
    ys, xs = np.mgrid[0:Hh, 0:W].astype(np.float32)
    sx, sy = x0 + (xs + 0.5) * cw / W, y0 + (ys + 0.5) * ch / Hh
    img = np.stack([map_coordinates(src[..., k], [sy, sx], order=3, mode="nearest") for k in range(3)], -1)
    img = np.clip(img, 0, 1) ** 2.2                               # to linear light for additive particles
    to_out = lambda px, py: ((px - x0) * W / cw, (py - y0) * Hh / ch)
    add = np.zeros_like(img)
    # debris + embers flowing along a curve into the black hole
    if SRC[i] is not None:
        rng = np.random.default_rng(10 + i); n = 650
        cx, cy, r0, _ = BH[i]; sx0, sy0 = SRC[i]
        ph = rng.random(n); spd = 0.12 + rng.random(n) * 0.18; off = rng.normal(0, 1, n); hot = rng.random(n)
        s = (ph + tl * spd) % 1.0; s = s ** 1.6                    # accelerate toward the hole
        bend = 60 * np.sin(np.pi * s)
        off2 = rng.normal(0, 1, n); px = lerp(sx0, cx, s) + off * 95 * (1 - s) ** 0.8 + bend * 0.8; py = lerp(sy0, cy + r0 * 0.6, s) + off2 * 60 * (1 - s)
        ox, oy = to_out(px, py); ok = (ox >= 1) & (ox < W - 2) & (oy >= 1) & (oy < Hh - 2)
        bright = (0.25 + 1.6 * s ** 2) * np.minimum(1, (1 - s) * 6)
        col = np.where((hot > 0.55)[:, None], np.array([1.0, 0.55, 0.18]), np.array([0.85, 0.8, 0.75])) * bright[:, None]
        xi, yi = ox[ok].astype(int), oy[ok].astype(int); np.add.at(add, (yi, xi), col[ok] * 0.55)
    # drifting foreground dust for depth (all scenes)
    rng = np.random.default_rng(99 + i); m = 220
    bx = (rng.random(m) * W + tl * (12 + rng.random(m) * 25)) % W; by = (rng.random(m) * Hh - tl * (8 + rng.random(m) * 18)) % Hh
    np.add.at(add, (by.astype(int), bx.astype(int)), np.array([0.5, 0.55, 0.65]) * rng.random((m, 1)) * 0.5)
    add = gaussian_filter(add, (1.4, 1.4, 0)) * 6 + gaussian_filter(add, (6, 6, 0)) * 10
    return img + add

def frame(n):
    t = n / FPS; parts = []
    for k, (i, a, b) in enumerate(SCENES):
        xin = XF.get((SCENES[k - 1][0], i), 0) if k else 0; xout = XF.get((i, SCENES[k + 1][0]), 0) if k < 4 else 0
        lo, hi = a - xin / 2, b + xout / 2
        if lo <= t < hi or (k == 4 and t >= lo):
            w = 1.0
            if xin and t < a + xin / 2: w = min(w, sst(a - xin / 2, a + xin / 2, t))
            if xout and t > b - xout / 2: w = min(w, 1 - sst(b - xout / 2, b + xout / 2, t))
            parts.append((i, max(0.0, t - a + (xin / 2 if t < a else 0)) if t >= a else 0.0, b - a, w))
    img = sum(render_scene(i, tl, d) * w for i, tl, d, w in parts) / max(1e-6, sum(w for *_, w in parts))
    img *= 1 - sst(28.5, 30.0, t)                                 # fade to black
    v = (np.mgrid[0:Hh, 0:W][0] / Hh - 0.5) ** 2 + (np.mgrid[0:Hh, 0:W][1] / W - 0.5) ** 2 * 0.6; img *= (1 - v * 0.5)[..., None]
    out = np.clip(img, 0, 1) ** (1 / 2.2) * 255 + np.random.default_rng(n).normal(0, 2.0, (Hh, W, 1))
    return Image.fromarray(np.clip(out, 0, 255).astype(np.uint8))

if __name__ == "__main__":
    if sys.argv[1] == "still": frame(int(float(sys.argv[2]) * FPS)).save(sys.argv[3]); sys.exit()
    wk, nw = int(sys.argv[1]), int(sys.argv[2]); out = H / "renders" / "frames"; out.mkdir(parents=True, exist_ok=True)
    for n in range(wk, int(T * FPS), nw):
        p = out / f"f_{n:04d}.png"
        if not p.exists(): frame(n).save(str(p) + ".tmp.png"); Path(str(p) + ".tmp.png").rename(p)
